-- Table: masterdata_coa
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_coa (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_code   VARCHAR(20)  NOT NULL UNIQUE,
    account_name   VARCHAR(150) NOT NULL,
    account_type   VARCHAR(20)  NOT NULL
                   CHECK (account_type IN ('asset', 'liability', 'equity', 'revenue', 'expense')),
    normal_balance VARCHAR(10)  NOT NULL
                   CHECK (normal_balance IN ('debit', 'credit')),
    parent_id      BIGINT REFERENCES masterdata_coa(id),
    is_header      BOOLEAN      NOT NULL DEFAULT FALSE,
    is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now()
);
